    if (model == null) {
      return error((RequestBuilder<TranscodeType>) null);
    }
    return error(cloneWithNullErrorAndThumbnail().load(model));
  }

  private RequestBuilder<TranscodeType> cloneWithNullErrorAndThumbnail() {
